"""Count log levels in app.log and write the result to report.json."""

import json
import re
from collections import Counter
from pathlib import Path

BASE_DIR = Path(__file__).resolve().parent
LOG_FILE = BASE_DIR / "app.log"
REPORT_FILE = BASE_DIR / "report.json"

LEVEL_RE = re.compile(
    r"\b(DEBUG|TRACE|INFO|WARNING|WARN|ERROR|FATAL|CRITICAL)\b"
)

ALIASES = {"WARNING": "WARN"}

CANONICAL_LEVELS = ("INFO", "WARN", "ERROR")


def count_levels(lines):
    counts = Counter()
    for line in lines:
        match = LEVEL_RE.search(line)
        if match:
            level = ALIASES.get(match.group(1), match.group(1))
            counts[level] += 1
    return counts


def build_report(lines):
    counts = count_levels(lines)
    report = {level: counts.get(level, 0) for level in CANONICAL_LEVELS}
    for level, count in counts.items():
        report.setdefault(level, count)
    return report


def main():
    lines = LOG_FILE.read_text(encoding="utf-8").splitlines()
    report = build_report(lines)
    REPORT_FILE.write_text(
        json.dumps(report, indent=2) + "\n", encoding="utf-8"
    )
    print(json.dumps(report, indent=2))


if __name__ == "__main__":
    main()

